--   mysql -u root -p < src/resources/db/ems_test_data_mysql.sql
-- Test logins: username = first initial + last name (e.g. dcarter), password = Welcome<empID>! (e.g. Welcome103!)
-- SSNs use the 9xx area range, which is never issued, so none belong to real people.

